import { PlaneGeometry, Mesh, Group, Color } from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, smoothstep, vec3, texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const { Group: ThreeGroup, Mesh: ThreeMesh, PlaneGeometry: ThreePlaneGeometry } = ctx.THREE;

  const root = new ThreeGroup();
  root.name = 'features-title';

  const timelines = [];
  const disposables = [];
  const handlers = {};

  const surface = new Color('#0b0b10');
  const ink = new Color('#16161d');
  const paper = '#e8ecf2';
  const accent = '#ff2a38';

  const backdropMaterial = new MeshBasicNodeMaterial();
  backdropMaterial.colorNode = mix(
    vec3(surface.r, surface.g, surface.b),
    vec3(ink.r, ink.g, ink.b),
    smoothstep(0.05, 0.95, uv().y)
  );

  const backdrop = new ThreeMesh(
    new ThreePlaneGeometry(7, 6),
    backdropMaterial
  );
  backdrop.name = 'engineered-gradient-backdrop';
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  disposables.push(backdrop.geometry, backdrop.material);

  const grainMaterial = new MeshBasicNodeMaterial({
    color: new Color('#16161d'),
    transparent: true,
    opacity: 0.42
  });

  const grainPlane = new ThreeMesh(
    new ThreePlaneGeometry(5.12, 3.2),
    grainMaterial
  );
  grainPlane.name = 'ceramic-grain-sprite';
  grainPlane.position.set(0, 0, -0.35);
  root.add(grainPlane);
  disposables.push(grainPlane.geometry, grainPlane.material);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: new Color(accent)
  });

  const accentLine = new ThreeMesh(
    new ThreePlaneGeometry(1.65, 0.045),
    accentMaterial
  );
  accentLine.name = 'signal-red-rule';
  accentLine.position.set(-1.55, -0.72, 0.08);
  root.add(accentLine);
  disposables.push(accentLine.geometry, accentLine.material);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const content = typeof item?.text === 'string' ? item.text : '';
    if (!content) continue;

    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: item.typography?.fontSize ?? 96,
      color: paper,
      align: 'left'
    });

    textObject.name = item.role ? `text-${item.role}` : 'headline';
    textObject.position.set(-2.35, 0.02, 0.12);
    root.add(textObject);
  }

  const billboard = (object) => {
    object.onBeforeRender = (_renderer, _scene, camera) => {
      object.quaternion.copy(camera.quaternion);
    };
  };

  billboard(grainPlane);

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((loadedTexture) => {
      loadedTexture.wrapS = ctx.THREE.ClampToEdgeWrapping;
      loadedTexture.wrapT = ctx.THREE.ClampToEdgeWrapping;
      loadedTexture.repeat.set(1, 1);
      loadedTexture.offset.set(0, 0);

      grainMaterial.map = loadedTexture;
      grainMaterial.colorNode = texture(loadedTexture);
      grainMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      if (timeline && typeof timeline.kill === 'function') timeline.kill();
    }

    for (const disposable of disposables) {
      if (disposable && typeof disposable.dispose === 'function') {
        disposable.dispose();
      }
    }

    root.traverse((object) => {
      if (object.onBeforeRender) object.onBeforeRender = null;
    });
  };

  return root;
}
